import path from "node:path";

const DEFAULT_DATABASE_PATH = "./data/dev.db";

/** Absolute path of the SQLite file, from DATABASE_URL or the local default. */
export function resolveDatabasePath(): string {
  const configured = process.env.DATABASE_URL?.trim() || DEFAULT_DATABASE_PATH;
  return configured === ":memory:"
    ? configured
    : path.resolve(/*turbopackIgnore: true*/ process.cwd(), configured);
}

/** Absolute path of the SQL migrations generated by drizzle-kit. */
export function migrationsFolder(): string {
  return path.resolve(/*turbopackIgnore: true*/ process.cwd(), "drizzle");
}
